mapper.select:
SELECT last_read_seq
FROM chat_read_state
WHERE user_id = #{userId} AND conversation_id = #{conversationId}

mapper.update:
UPDATE chat_read_state
SET last_read_seq = GREATEST(last_read_seq, #{seq}),
    updated_at = #{now}
WHERE user_id = #{userId} AND conversation_id = #{conversationId}
